import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p87_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor pointwise_conv1x1_cuda(torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("pointwise_conv1x1", &pointwise_conv1x1_cuda, "Pointwise 1x1 convolution (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_OC 4
#define TILE_NHW 256

__global__ void pointwise_conv1x1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int B, int IC, int OC, int H, int W,
    bool has_bias
) {
    int nhw_base = blockIdx.x * TILE_NHW + threadIdx.x;
    int oc_base = blockIdx.y * TILE_OC;
    int NHW = B * H * W;

    if (nhw_base >= NHW) return;

    int b = nhw_base / (H * W);
    int hw = nhw_base % (H * W);
    int h = hw / W;
    int w = hw % W;

    for (int oc_offset = 0; oc_offset < TILE_OC; ++oc_offset) {
        int oc = oc_base + oc_offset;
        if (oc >= OC) break;

        float sum = 0.0f;
        for (int ic = 0; ic < IC; ++ic) {
            int input_idx = ((b * IC + ic) * H + h) * W + w;
            int weight_idx = oc * IC + ic;
            sum += input[input_idx] * weight[weight_idx];
        }

        if (has_bias) {
            sum += bias[oc];
        }

        int output_idx = ((b * OC + oc) * H + h) * W + w;
        output[output_idx] = sum;
    }
}

torch::Tensor pointwise_conv1x1_cuda(torch::Tensor input, torch::Tensor weight, torch::optional<torch::Tensor> bias) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");

    input = input.contiguous();
    weight = weight.contiguous();

    int B = input.size(0);
    int IC = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int OC = weight.size(0);

    TORCH_CHECK(weight.size(1) == IC, "weight channels must match input channels");
    TORCH_CHECK(weight.size(2) == 1 && weight.size(3) == 1, "weight must be 1x1");

    bool has_bias = bias.has_value();
    const float* bias_ptr = nullptr;
    if (has_bias) {
        auto bias_tensor = bias.value().contiguous();
        TORCH_CHECK(bias_tensor.is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias_tensor.dtype() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias_tensor.size(0) == OC, "bias size must match output channels");
        bias_ptr = bias_tensor.data_ptr<float>();
    }

    auto output = torch::empty({B, OC, H, W}, input.options());

    int NHW = B * H * W;
    dim3 threads(TILE_NHW);
    dim3 blocks((NHW + TILE_NHW - 1) / TILE_NHW, (OC + TILE_OC - 1) / TILE_OC);

    pointwise_conv1x1_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        B, IC, OC, H, W,
        has_bias
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
